import json, subprocess, urllib.parse, sys
from datetime import datetime, timedelta, timezone

base = "https://www.googleapis.com/calendar/v3"
token = "<TOKEN>"

def curl_json(url, method="GET"):
    cmd = ["curl", "-s", "-X", method, "-H", f"Authorization: Bearer {token}", url]
    p = subprocess.run(cmd, capture_output=True, text=True)
    if p.returncode != 0:
        sys.stderr.write(p.stderr)
    try:
        return json.loads(p.stdout)
    except Exception:
        sys.stderr.write("RAW:" + p.stdout[:3000])
        raise

items = []
page = None
while True:
    url = f"{base}/users/me/calendarList?minAccessRole=owner&maxResults=250"
    if page:
        url += "&pageToken=" + urllib.parse.quote(page)
    d = curl_json(url)
    items.extend(d.get("items", []))
    page = d.get("nextPageToken")
    if not page:
        break

print("owned_calendars", len(items))
for c in items:
    print("CAL", c["id"], c.get("summary"), c.get("accessRole"))

la_tz = timezone(timedelta(hours=-7))

def local_start_date(item):
    st = item.get("originalStartTime") or item.get("start")
    if not st:
        return None
    if "date" in st:
        return datetime.fromisoformat(st["date"]).date()
    dt = datetime.fromisoformat(st["dateTime"])
    return dt.astimezone(la_tz).date()

start_date = datetime(2018, 6, 18).date()
end_date = datetime(2018, 6, 22).date()
timeMin = "2018-06-17T23:59:59-07:00"
timeMax = "2018-06-23T00:00:00-07:00"

candidates = []
for c in items:
    cid = c["id"]
    page = None
    while True:
        url = (
            f"{base}/calendars/{urllib.parse.quote(cid, safe='')}/events"
            f"?singleEvents=true&maxResults=2500&timeMin={urllib.parse.quote(timeMin)}&timeMax={urllib.parse.quote(timeMax)}"
        )
        if page:
            url += "&pageToken=" + urllib.parse.quote(page)
        d = curl_json(url)
        for e in d.get("items", []):
            if e.get("summary") == "Vendor sync":
                ds = local_start_date(e)
                if ds and start_date <= ds <= end_date:
                    candidates.append({
                        "calendarId": cid,
                        "eventId": e["id"],
                        "summary": e.get("summary"),
                        "start": e.get("originalStartTime") or e.get("start"),
                        "end": e.get("end"),
                        "localStartDate": ds.isoformat()
                    })
        page = d.get("nextPageToken")
        if not page:
            break

print("candidates", len(candidates))
for x in candidates:
    print(x)
